cat > parts/room-30.mjs <<'EOF'
// P4 stair strip
// One cell wide: the attic flight (x54, z15->11) fills the strip, so there is no floor for furniture. The room is
// lit by one hanging lantern at the foot of the stair, under the attic floor at z15 (y6, head room kept clear).
// Light falls off one per block: z10..15 all read 10+ from it.
export function build(g) {
  if (g.isAir(54, 6, 15)) g.set(54, 6, 15, "lantern", { hanging: "true" });
}
EOF
